// Assemble the system prompt from the tenant persona + scoped context + the live
// queue snapshot, then carry the routing fields forward for the LLM, Route, Send
// and Escalate nodes.
const norm = $('Normalize').item.json;
const ctx = $('Get Context').item.json;
const queue = ($json && $json.data) || null; // Queue Snapshot tool result
const p = ctx.persona || {};
const agent = (p.agents && p.agents[0]) || null;
const personaName = agent ? agent.name : 'Assistant';
const rupiah = (n) => 'Rp ' + Number(n || 0).toLocaleString('id-ID');
const lines = [];
lines.push('You are ' + (agent ? agent.name + ', a ' + String(agent.role || '').replace(/_/g, ' ') : 'a helpful assistant') + ' for an Indonesian car wash & detailing business.');
if (agent && agent.prompt) lines.push(agent.prompt);
if (p.basePrompt) lines.push(p.basePrompt);
lines.push("Reply in the customer's language (Bahasa Indonesia by default). Be concise and warm. Use only the data provided below; never invent prices, order numbers or membership details.");
lines.push('IF you cannot help, the customer is angry, asks to speak with a human, or requests something outside your knowledge or another person\'s data: reply with EXACTLY the token [[ESCALATE]] and nothing else.');
if (p.productKnowledge) lines.push('\nBUSINESS KNOWLEDGE:\n' + p.productKnowledge);
const pub = ctx.publicInfo || {};
if (pub.services && pub.services.length) lines.push('\nSERVICES & PRICES:\n' + pub.services.slice(0, 40).map((s) => '- [' + s.unit + '] ' + s.name + ': ' + rupiah(s.price)).join('\n'));
if (pub.plans && pub.plans.length) lines.push('\nMEMBERSHIP PLANS:\n' + pub.plans.map((m) => '- ' + m.name + ': ' + rupiah(m.price) + ' (' + m.durationMonths + ' mo)').join('\n'));
if (queue && typeof queue.ordersWaitingToday === 'number') lines.push('\nLIVE QUEUE: ' + queue.ordersWaitingToday + ' order(s) waiting today.');
if (ctx.customer && ctx.context) {
  const c = ctx.context;
  lines.push('\nCUSTOMER: ' + ctx.customer.name + '.');
  if (c.memberships && c.memberships.length) lines.push('Memberships: ' + c.memberships.map((m) => m.plan + ' (' + m.status + ', ends ' + m.endDate + ')').join('; '));
  if (c.activeQueue) lines.push('Current queue: order ' + c.activeQueue.orderNumber + ', position ' + c.activeQueue.position + ', status ' + c.activeQueue.status + '.');
  if (c.recentOrders && c.recentOrders.length) lines.push('Recent orders: ' + c.recentOrders.map((o) => o.orderNumber + ' (' + o.status + ')').join('; '));
} else {
  lines.push('\nThe sender is not a registered customer yet — share only public info and invite them to visit or register.');
}
const messages = [
  { role: 'system', content: lines.join('\n') },
  { role: 'user', content: norm.message.text },
];
return { callbackBaseUrl: norm.callbackBaseUrl, bridgeToken: norm.bridgeToken, message: norm.message, personaName, messages };
